<script setup>
import { computed, ref, onMounted, onBeforeUnmount } from 'vue'
import AppHeader from '@/components/AppHeader.vue'
import UiButton from '@/components/UiButton.vue'
import MerchantProductsModal from '@/components/MerchantProductsModal.vue'
import { http } from '@/api/http'
import { unwrapResult } from '@/utils/result'

const rows = ref([]), counts = ref([]), total = ref(0), page = ref(1), busy = ref(false), error = ref(''), business = ref('ALL'), status = ref('ALL'), keyword = ref(''), selected = ref(null)
const labels = { ACTIVE: '服务中', EXPIRING: '30天内到期', EXPIRED: '已到期', PAUSED: '已暂停', UNLIMITED: '长期有效', NOT_OPEN: '授权已撤销' }
const cards = computed(() => [{ status: 'ALL', title: '已购服务', value: counts.value.reduce((n, r) => n + Number(r.count), 0), tone: 'blue' }, { status: 'EXPIRING', title: '30天内到期', value: counts.value.find(r => r.serviceStatus === 'EXPIRING')?.count || 0, tone: 'amber' }, { status: 'EXPIRED', title: '已到期待续费', value: counts.value.find(r => r.serviceStatus === 'EXPIRED')?.count || 0, tone: 'rose' }, { status: 'PAUSED', title: '暂停的服务', value: counts.value.find(r => r.serviceStatus === 'PAUSED')?.count || 0, tone: 'slate' }])
let generation = 0, disposed = false
async function load(reset = false) {
  if (reset) page.value = 1
  const version = ++generation
  busy.value = true; error.value = ''; rows.value = []
  try { const value = unwrapResult(await http.get('/platform/product-subscriptions', { params: { business: business.value, status: status.value, keyword: keyword.value, page: page.value } })); if (!disposed && version === generation) { rows.value = value.list; counts.value = value.counts; total.value = value.total } }
  catch (e) { if (!disposed && version === generation) error.value = e.message || '服务列表暂时无法加载' }
  finally { if (!disposed && version === generation) busy.value = false }
}
function pick(value) { status.value = value; load(true) }
function move(delta) { page.value += delta; load() }
onMounted(() => load())
onBeforeUnmount(() => { disposed = true; generation++ })
</script>

<template>
  <div class="min-h-screen bg-slate-50">
    <AppHeader /><main class="renewals-page">
      <header class="renewals-heading"><div><span class="eyebrow">PRODUCT SUBSCRIPTIONS</span><h1>服务期限与续费</h1><p>点餐与商城分别管理，一眼找到需要跟进的商家。</p></div><UiButton variant="secondary" :disabled="busy" @click="load()">刷新列表</UiButton></header>
      <div class="renewal-cards"><button v-for="card in cards" :key="card.status" :class="[card.tone, { selected: status === card.status }]" @click="pick(card.status)"><span>{{ card.title }}</span><strong>{{ error ? '—' : card.value }}</strong><small>{{ card.status === 'ALL' ? '按产品计数，同一门店可有两项服务' : '点击筛选查看' }}</small></button></div>
      <section class="renewal-panel"><form class="renewal-filters" @submit.prevent="load(true)"><label>业务产品<select v-model="business" aria-label="业务产品" @change="load(true)"><option value="ALL">全部产品</option><option value="DINING">点餐服务</option><option value="MALL">商城服务</option></select></label><label>服务状态<select v-model="status" aria-label="服务状态" @change="load(true)"><option value="ALL">全部状态</option><option v-for="(label, value) in labels" :key="value" :value="value">{{ label }}</option></select></label><label class="merchant-search">查找商家<input v-model="keyword" aria-label="商户名称" placeholder="输入门店名称" maxlength="100" /></label><UiButton type="submit" :loading="busy">查询</UiButton></form><p v-if="error" role="alert" class="renewal-error">{{ error }}<button @click="load()">重试</button></p><div class="renewal-table-wrap"><table><thead><tr><th>门店</th><th>业务产品</th><th>服务状态</th><th>到期日期</th><th>续费提醒</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="`${row.id}:${row.productType}`"><td><strong>{{ row.name }}</strong><small>门店 #{{ row.id }} · {{ row.isActive ? '账号正常' : '账号已停用' }}</small></td><td><span class="product-pill" :class="row.productType.toLowerCase()">{{ row.productType === 'MALL' ? '商城服务' : '点餐服务' }}</span><small v-if="row.application">应用 #{{ row.application.id }}</small></td><td><span class="service-pill" :class="row.status.toLowerCase()">{{ labels[row.status] }}</span></td><td>{{ row.expiresOn || '长期有效' }}</td><td :class="{ 'expiry-warning': ['EXPIRED', 'EXPIRING'].includes(row.status) }">{{ row.status === 'EXPIRED' ? `已过期 ${Math.abs(row.daysRemaining)} 天` : row.status === 'EXPIRING' ? `剩余 ${row.daysRemaining} 天` : '—' }}</td><td><UiButton variant="secondary" @click="selected = row">{{ ['EXPIRED', 'EXPIRING'].includes(row.status) ? '去续费' : '管理服务' }}</UiButton></td></tr><tr v-if="!rows.length"><td colspan="6" class="renewal-empty">{{ busy ? '正在读取服务列表…' : error ? '服务列表暂不可用' : '当前条件下没有已购服务' }}</td></tr></tbody></table></div><footer class="renewal-pagination"><span>共 {{ total }} 项服务 · 第 {{ page }} 页</span><UiButton variant="secondary" :disabled="busy || page <= 1" @click="move(-1)">上一页</UiButton><UiButton variant="secondary" :disabled="busy || page * 20 >= total" @click="move(1)">下一页</UiButton></footer></section><p class="renewal-note">到期会停止该产品新增交易，历史订单仍可履约和售后；另一项产品按自己的授权与期限运行。</p>
    </main><MerchantProductsModal :merchant="selected" :initial-product="selected?.productType || ''" @close="selected = null" @saved="load()" />
  </div>
</template>

<style scoped>
.renewals-page{max-width:1280px;margin:0 auto;padding:34px 26px 44px;color:#33435c}.renewals-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:28px}.eyebrow{font-size:10px;color:#9ba8bb;letter-spacing:1.8px}.renewals-heading h1{font-size:26px;letter-spacing:-.6px;font-weight:650;margin:9px 0}.renewals-heading p{font-size:13px;color:#91a0b5;margin:0}.renewal-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin-bottom:24px}.renewal-cards button{background:white;border:1px solid #e5eaf3;border-radius:12px;text-align:left;padding:22px;display:grid;gap:16px;cursor:pointer}.renewal-cards button.selected{border-color:#91a7eb;box-shadow:0 3px 12px #375aca09}.renewal-cards button>span{font-size:12px;color:#8b99ad}.renewal-cards strong{font-size:31px;font-weight:600;line-height:1;color:#4263ba}.renewal-cards .amber strong{color:#d6a04e}.renewal-cards .rose strong{color:#d5888b}.renewal-cards .slate strong{color:#8392a7}.renewal-cards small{font-size:10px;color:#a3afbf;line-height:1.6}.renewal-panel{background:white;border:1px solid #e5eaf3;border-radius:12px;padding:23px}.renewal-filters{display:flex;align-items:end;gap:14px;margin-bottom:22px;flex-wrap:wrap}.renewal-filters label{display:grid;gap:7px;font-size:11px;color:#93a0b4;min-width:150px}.renewal-filters select,.renewal-filters input{padding:8px 10px;border:1px solid #e2e8f1;border-radius:6px;font-size:12px;color:#5b6e87;background:white}.merchant-search{flex:1;max-width:310px}.renewal-table-wrap{overflow:auto}table{width:100%;min-width:760px;border-collapse:collapse;text-align:left}th{background:#f7f9fc;font-size:11px;color:#8c9bb0;font-weight:500;padding:13px 12px}td{padding:20px 12px;border-bottom:1px solid #edf1f7;font-size:12px;color:#7d8da5}td strong{font-size:13px;color:#43546e;font-weight:500}td small{display:block;font-size:10px;color:#a5b1c1;margin-top:7px}.product-pill,.service-pill{font-size:11px;padding:5px 8px;border-radius:5px;white-space:nowrap}.product-pill.dining{color:#647ec3;background:#eef2fd}.product-pill.mall{color:#4a9c87;background:#eef8f4}.service-pill{background:#f1f4f8;color:#93a0b0}.service-pill.expiring{background:#fff5e7;color:#c39a5e}.service-pill.expired{background:#fff0f0;color:#cd8484}.service-pill.active,.service-pill.unlimited{background:#eef8f4;color:#67a58d}.expiry-warning{color:#c0935c}.renewal-empty{text-align:center;padding:55px 20px;color:#a0acbd}.renewal-pagination{display:flex;align-items:center;gap:10px;margin-top:20px}.renewal-pagination>span{font-size:11px;color:#9aa7b9;margin-right:auto}.renewal-note{font-size:11px;color:#99a6b9;line-height:1.8;margin-top:20px}.renewal-error{color:#bb7777;font-size:12px}.renewal-error button{margin-left:10px;color:#4263ba}@media(max-width:750px){.renewals-page{padding:25px 16px}.renewals-heading{align-items:flex-start}.renewals-heading h1{font-size:23px}.renewal-cards{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.renewal-cards button{padding:17px;gap:12px}.renewal-cards strong{font-size:26px}.renewal-panel{padding:16px}.renewal-filters{gap:12px}.renewal-filters label{min-width:0;flex:1}.renewal-filters .merchant-search{min-width:100%;max-width:none}.renewals-heading p{font-size:11px}.renewal-pagination>span{font-size:10px}}
</style>
